suppressPackageStartupMessages({library(data.table);library(readxl)})
out<-'audit/20261011_all_groups_algorithm_audit/kla_tissues';sp<-unique(fread(file.path(out,'source_evidence.csv'))[,.(SourceFile,AccessionField)]);all<-list()
for(i in seq_len(nrow(sp))){p<-sp$SourceFile[i];x<-if(grepl('0005-tables3',p))as.data.table(read_excel(p,skip=12))else if(grepl('mmc1.xlsx',p))as.data.table(read_excel(p,skip=1))else if(grepl('PeptideGroups',p))as.data.table(read.delim(p,check.names=FALSE,quote='"',comment.char=''))else fread(p,quote='',integer64='double');cols<-intersect(c('Protein','Proteins','Leading proteins','Leading razor protein','Master Protein Accessions','Protein accession','Proteins accession','PTM.ProteinId'),names(x));z<-lapply(cols,function(c){ix<-which(grepl('REV__|CON__|DECOY|CONTAM',x[[c]],ignore.case=TRUE));if(!length(ix))return(NULL);data.table(SourceFile=p,SourceRow=ix+2L,Column=c,Value=x[[c]][ix],ReverseFlag=if('Reverse'%in%names(x))x$Reverse[ix]else'',ContaminantFlag=if('Potential contaminant'%in%names(x))x[['Potential contaminant']][ix]else'',AnalysisColumn=sp$AccessionField[i],AnalysisValue=x[[sp$AccessionField[i]]][ix])});all[[i]]<-rbindlist(z,fill=TRUE)}
a<-rbindlist(all,fill=TRUE);fwrite(a,file.path(out,'all_id_fields_flagged_rows.csv'));print(a[,.(Rows=.N,Hidden=sum(ReverseFlag!='+'&ContaminantFlag!='+')),by=.(SourceFile,Column)])
print(a[Column=='Protein'&ReverseFlag!='+'&ContaminantFlag!='+'])
